const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Cambodia geometry
  const cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Cambodia'))
    .geometry();

  // 2. Load MODIS Active Fire product
  const fireCollection = ee.ImageCollection('MODIS/061/MOD14A1');

  // 3. Filter for two periods
  const aug2017 = fireCollection
    .filterDate('2017-08-01', '2017-08-31')
    .filterBounds(cambodia);

  const feb2018 = fireCollection
    .filterDate('2018-02-01', '2018-02-28')
    .filterBounds(cambodia);

  // 4. Check collection sizes
  const aug2017Size = aug2017.size().getInfo();
  const feb2018Size = feb2018.size().getInfo();

  console.log(`Aug 2017 Images: ${aug2017Size}`);
  console.log(`Feb 2018 Images: ${feb2018Size}`);

  if (aug2017Size === 0 || feb2018Size === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Count fire detections using FireMask band (values 7-9 indicate fires)
  const countFires = (collection, geometry) => {
    const fireMask = collection.select('FireMask').map(img => 
      img.gte(7).and(img.lte(9))
    );
    const totalFires = fireMask.sum();

    const result = totalFires.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    return result.get('FireMask').getInfo();
  };

  // 6. Calculate fire counts
  const aug2017Fires = countFires(aug2017, cambodia);
  const feb2018Fires = countFires(feb2018, cambodia);

  console.log(`Aug 2017 Fire Detections: ${aug2017Fires}`);
  console.log(`Feb 2018 Fire Detections: ${feb2018Fires}`);

  // 7. Validate results
  if (aug2017Fires === null || feb2018Fires === null || 
      isNaN(aug2017Fires) || isNaN(feb2018Fires)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and answer
  if (feb2018Fires > aug2017Fires) {
    console.log('Feb 2018 has more fire detections than Aug 2017.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Feb 2018 does not have more fire detections than Aug 2017.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
